-- ===== ME fix: Platner won the June-9 D primary but WITHDREW 2026-07-08 (Politico-reported
-- allegation); ME Dem convention picks replacement by 2026-07-27. Keep primary record intact. =====
UPDATE essentials.race_candidates SET candidate_status = 'withdrawn'
WHERE id = 'd08e6373-fd46-466a-9dc2-86b6f3e62337' AND candidate_status <> 'withdrawn';

-- ===== MA fixes (audit 2026-07-10): Bech withdrew from R primary (not on any ballot);
-- Gates + Rikleen withdrew/DQ'd from the D primary (Rikleen endorsed Markey). =====
UPDATE essentials.race_candidates SET candidate_status = 'withdrawn'
WHERE race_id = '65b552af-ac06-45ac-bafb-f21f2015a4ec' AND full_name = 'Nathan Bech' AND candidate_status <> 'withdrawn';
UPDATE essentials.race_candidates SET candidate_status = 'withdrawn'
WHERE race_id = '7eda9036-9eb6-4f2d-86a1-c1e7cbb51864' AND full_name IN ('William Gates','Alexander Rikleen') AND candidate_status <> 'withdrawn';

